def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_D = 0
    my_D = 0
    for me, opp in history:
        if opp == 'D':
            opp_D += 1
        if me == 'D':
            my_D += 1

    last_me, last_opp = history[-1]

    streak_opp_D = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            streak_opp_D += 1
        else:
            break

    if my_D > 0:
        exploit = False
        for i in range(n-1):
            if history[i][0] == 'D' and history[i+1][1] == 'C':
                exploit = True
                break
        if exploit and opp_D / n < 0.5:
            return 'D'

    if streak_opp_D >= 5:
        return 'D'

    if last_opp == 'D':
        if streak_opp_D == 1:
            if opp_D / n < 0.25:
                return 'C'
            else:
                return 'D'
        elif streak_opp_D == 2:
            return 'D'
        elif streak_opp_D == 3:
            return 'D'
        elif streak_opp_D == 4:
            return 'C'
        else:
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
